<?php
declare(strict_types=1);
use Sand\Iam\Example\ProviderB\{ContextVerifier,ProcessStore,ProviderException,ProviderProtocol};
final class AllowVerifier implements ContextVerifier {public function verify(string $context,string $request):array{return['context_id'=>'ctx-1','workload_client_id'=>10,'organization_id'=>20,'service_code'=>ProviderProtocol::SERVICE_CODE,'audience'=>ProviderProtocol::AUDIENCE,'actions'=>[ProviderProtocol::ACTION]];}}
final class DenyVerifier implements ContextVerifier {public function verify(string $context,string $request):array{throw new ProviderException('PROVIDER_B_CONTEXT_DENIED',403);}}
final class RevocableVerifier implements ContextVerifier {public bool $revoked=false;public int $calls=0;public function verify(string $context,string $request):array{++$this->calls;if($this->revoked)throw new ProviderException('PROVIDER_B_CONTEXT_DENIED',403);return['context_id'=>'ctx-1','workload_client_id'=>10,'organization_id'=>20,'service_code'=>ProviderProtocol::SERVICE_CODE,'audience'=>ProviderProtocol::AUDIENCE,'actions'=>[ProviderProtocol::ACTION]];}}
final class MemoryStore implements ProcessStore {public string $body='body';public int $calls=0;public int $effects=0;private array $rows=[];public function process(array $claims,string $doc,string $key,string $request):array{++$this->calls;$hash=hash('sha256',$this->body);$bytes=strlen($this->body);$row=$this->rows[$key]??null;if($row!==null){if($row['content_sha256']!==$hash||$row['content_bytes']!==$bytes||$row['document_id']!==$doc)throw new ProviderException('PROVIDER_B_IDEMPOTENCY_KEY_REUSED',409);$row['replayed']=true;return $row;}++$this->effects;return $this->rows[$key]=['process_id'=>$this->effects,'document_id'=>$doc,'content_sha256'=>$hash,'content_bytes'=>$bytes,'replayed'=>false];}}
